/**
 * Private helpers shared by the service layer.
 *
 * Two jobs only: build the `PermissionResource` descriptors `can()` expects
 * from a loaded row, and stamp the `EventEnvelope` every domain event carries.
 * Neither re-implements a cross-cutting concern — they are adapters onto
 * `@/lib/permissions` and `@/lib/event-bus`.
 */
import { toIsoTimestamp } from "@/types/common";
import type { Comment } from "@/types/comment";
import type { OrgId, UserId } from "@/types/common";
import type { EventEnvelope } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor, Member } from "@/types/member";
import type { PermissionResource } from "@/types/permission";
import type { Project } from "@/types/project";
import type { WebhookId } from "@/types/common";

/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
export class NotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(
    readonly entity: string,
    readonly id: string,
  ) {
    super(`${entity} ${id} was not found`);
    this.name = "NotFoundError";
  }
}

/** Unwraps a repository read, turning the `null` case into a domain error. */
export function requireFound<T>(
  value: T | null | undefined,
  entity: string,
  id: string,
): T {
  if (value === null || value === undefined) {
    throw new NotFoundError(entity, id);
  }
  return value;
}

export function orgResource(orgId: OrgId): PermissionResource {
  return { kind: "organization", orgId };
}

export function billingResource(orgId: OrgId): PermissionResource {
  return { kind: "billing", orgId };
}

export function activityResource(orgId: OrgId): PermissionResource {
  return { kind: "activity", orgId };
}

export function notificationResource(
  orgId: OrgId,
  recipientId: UserId,
): PermissionResource {
  return { kind: "notification", orgId, recipientId };
}

export function webhookResource(
  orgId: OrgId,
  webhookId: WebhookId | null,
): PermissionResource {
  return { kind: "webhook", orgId, webhookId };
}

export function memberResource(member: Member): PermissionResource {
  return {
    kind: "member",
    orgId: member.orgId,
    memberId: member.id,
    targetUserId: member.userId,
    targetRole: member.role,
  };
}

export function projectResource(project: Project): PermissionResource {
  return {
    kind: "project",
    orgId: project.orgId,
    projectId: project.id,
    visibility: project.visibility,
    leadId: project.leadId,
  };
}

export function issueResource(issue: Issue): PermissionResource {
  return {
    kind: "issue",
    orgId: issue.orgId,
    projectId: issue.projectId,
    issueId: issue.id,
    authorId: issue.authorId,
    assigneeId: issue.assigneeId,
  };
}

export function commentResource(comment: Comment): PermissionResource {
  return {
    kind: "comment",
    orgId: comment.orgId,
    commentId: comment.id,
    authorId: comment.authorId,
  };
}

/** The three fields the bus stamps on every payload. */
export function envelope(orgId: OrgId, actorId: UserId | null): EventEnvelope {
  return { orgId, actorId, occurredAt: toIsoTimestamp(new Date()) };
}

/** Same envelope, taken from an `Actor` rather than assembled by hand. */
export function actorEnvelope(actor: Actor): EventEnvelope {
  return envelope(actor.orgId, actor.userId);
}

/** Names the fields an update actually changed, for `issue.updated`. */
export function changedFields<T extends object>(
  before: T,
  after: T,
): readonly string[] {
  return Object.keys(after).filter(
    (key) =>
      JSON.stringify(before[key as keyof T]) !==
      JSON.stringify(after[key as keyof T]),
  );
}

/**
 * Cross-cutting constants that are neither plan limits nor flags (page sizes,
 * edit windows, retry counts).
 *
 * Quotas live in `@/config/plan-limits` and rollout gates in
 * `@/config/feature-flags`; anything that is neither — a default page size, a
 * grace window, a retry budget — belongs here so the number exists once.
 */

/** Rows per page for every cursor-paginated list unless the caller overrides. */
export const DEFAULT_PAGE_SIZE: number = 25;

/** Upper bound the pagination schemas clamp `limit` to. */
export const MAX_PAGE_SIZE: number = 100;

/** How long after posting a comment its author may still edit it. */
export const COMMENT_EDIT_WINDOW_MINUTES: number = 15;

/** Delivery attempts before the webhook dispatcher parks a delivery. */
export const WEBHOOK_MAX_ATTEMPTS: number = 5;

/** Hard cap on entries rendered in one digest email. */
export const DIGEST_MAX_ENTRIES: number = 50;

/** How far ahead the overdue job looks when collecting due issues. */
export const OVERDUE_LOOKAHEAD_HOURS: number = 24;

"use client";

/**
 * Organization profile and settings editor.
 *
 * Owner D. Private to the settings route. `updateOrganizationSchema` accepts a
 * *partial* settings block, so the form only sends the keys it renders — the
 * service merges them over what is stored.
 */

import { useActionState } from "react";
import { updateOrganizationAction } from "@/actions/organizations/update-organization";
import { fieldErrorsFromZod } from "@/lib/errors";
import { updateOrganizationSchema } from "@/schemas/organization";
import type { ActionResult } from "@/types/api";
import type { Organization } from "@/types/organization";

export type OrganizationSettingsFormProps = {
  org: Organization;
  disabled: boolean;
};

type SettingsState = ActionResult<Organization> | null;

export function OrganizationSettingsForm(props: OrganizationSettingsFormProps) {
  const { org, disabled } = props;

  const [state, submit, pending] = useActionState<SettingsState, FormData>(
    async (_previous, formData) => {
      const logoUrl = String(formData.get("logoUrl") ?? "").trim();

      const parsed = updateOrganizationSchema.safeParse({
        orgId: org.id,
        name: String(formData.get("name") ?? ""),
        logoUrl: logoUrl.length === 0 ? null : logoUrl,
        settings: {
          allowPublicProjects: formData.get("allowPublicProjects") === "on",
          requireTwoFactor: formData.get("requireTwoFactor") === "on",
          digestHourUtc: Number(formData.get("digestHourUtc") ?? 7),
        },
      });

      if (!parsed.success) {
        return {
          ok: false,
          error: {
            code: "validation_failed",
            message: "Check the fields below.",
            fieldErrors: fieldErrorsFromZod(parsed.error),
          },
        };
      }

      return updateOrganizationAction(parsed.data);
    },
    null,
  );

  const fieldErrors = state?.ok === false ? (state.error.fieldErrors ?? {}) : {};

  return (
    <form action={submit} className="space-y-6">
      {state?.ok === true ? (
        <p className="rounded bg-emerald-50 px-3 py-2 text-sm text-emerald-700">
          Settings saved.
        </p>
      ) : null}
      {state?.ok === false && state.error.code === "forbidden" ? (
        <p role="alert" className="rounded bg-rose-50 px-3 py-2 text-sm text-rose-700">
          Your role does not allow changing organization settings.
        </p>
      ) : null}

      <div className="space-y-1">
        <label htmlFor="name" className="text-sm font-medium">
          Organization name
        </label>
        <input
          id="name"
          name="name"
          defaultValue={org.name}
          disabled={disabled}
          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm disabled:bg-slate-100"
        />
        {fieldErrors.name !== undefined ? (
          <p className="text-xs text-rose-600">{fieldErrors.name[0]}</p>
        ) : null}
      </div>

      <div className="space-y-1">
        <label htmlFor="logoUrl" className="text-sm font-medium">
          Logo URL
        </label>
        <input
          id="logoUrl"
          name="logoUrl"
          type="url"
          defaultValue={org.logoUrl ?? ""}
          disabled={disabled}
          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm disabled:bg-slate-100"
        />
      </div>

      <div className="space-y-1">
        <label htmlFor="digestHourUtc" className="text-sm font-medium">
          Digest hour (UTC)
        </label>
        <input
          id="digestHourUtc"
          name="digestHourUtc"
          type="number"
          min={0}
          max={23}
          defaultValue={org.settings.digestHourUtc}
          disabled={disabled}
          className="w-24 rounded-md border border-slate-300 px-3 py-2 text-sm disabled:bg-slate-100"
        />
        <p className="text-xs text-slate-500">
          The daily digest job runs once an hour and picks up organizations whose
          hour has come round.
        </p>
      </div>

      <label className="flex items-center gap-2 text-sm">
        <input
          type="checkbox"
          name="allowPublicProjects"
          defaultChecked={org.settings.allowPublicProjects}
          disabled={disabled}
        />
        Allow projects to be made public
      </label>

      <label className="flex items-center gap-2 text-sm">
        <input
          type="checkbox"
          name="requireTwoFactor"
          defaultChecked={org.settings.requireTwoFactor}
          disabled={disabled}
        />
        Require two-factor authentication
      </label>

      <button
        type="submit"
        disabled={disabled || pending}
        className="rounded-md bg-indigo-600 px-4 py-2 text-sm font-medium text-white disabled:opacity-60"
      >
        {pending ? "Saving…" : "Save settings"}
      </button>
    </form>
  );
}

