1	/** `slugify`, reserved slugs and `uniqueSlug` suffixing. */
2	import { describe, expect, it } from "vitest";
3	import {
4	  InvalidSlugError,
5	  RESERVED_SLUGS,
6	  SLUG_MAX_LENGTH,
7	  assertValidSlug,
8	  isReservedSlug,
9	  isValidSlug,
10	  projectKeyFromName,
11	  slugify,
12	  uniqueSlug,
13	} from "@/lib/slug";
14	
15	describe("lib/slug", () => {
16	  it("lowercases and hyphenates a display name", () => {
17	    expect(slugify("Website Relaunch")).toBe("website-relaunch");
18	    expect(slugify("  Acme   Corp  ")).toBe("acme-corp");
19	  });
20	
21	  it("strips diacritics and punctuation", () => {
22	    expect(slugify("Café Münster")).toBe("cafe-munster");
23	    expect(slugify("Q3 — Roadmap!")).toBe("q3-roadmap");
24	  });
25	
26	  it("collapses runs of separators and trims leading/trailing hyphens", () => {
27	    expect(slugify("--hello___world--")).toBe("hello-world");
28	  });
29	
30	  it("truncates to the maximum length without a trailing hyphen", () => {
31	    const slug = slugify("a".repeat(80));
32	    expect(slug.length).toBe(SLUG_MAX_LENGTH);
33	    expect(slug.endsWith("-")).toBe(false);
34	  });
35	
36	  it("returns an empty string when there is nothing sluggable", () => {
37	    expect(slugify("!!!")).toBe("");
38	  });
39	
40	  it("validates length and shape", () => {
41	    expect(isValidSlug("acme")).toBe(true);
42	    expect(isValidSlug("a")).toBe(false);
43	    expect(isValidSlug("Acme")).toBe(false);
44	    expect(isValidSlug("acme--corp")).toBe(false);
45	    expect(isValidSlug("-acme")).toBe(false);
46	    expect(isValidSlug("a".repeat(SLUG_MAX_LENGTH + 1))).toBe(false);
47	  });
48	
49	  it("knows the router's reserved slugs", () => {
50	    expect(isReservedSlug("settings")).toBe(true);
51	    expect(isReservedSlug("acme")).toBe(false);
52	    for (const reserved of RESERVED_SLUGS) {
53	      expect(isReservedSlug(reserved), reserved).toBe(true);
54	    }
55	  });
56	
57	  it("throws InvalidSlugError for malformed and reserved slugs", () => {
58	    expect(() => assertValidSlug("acme")).not.toThrow();
59	    expect(() => assertValidSlug("Acme!")).toThrow(InvalidSlugError);
60	    expect(() => assertValidSlug("billing")).toThrow(/reserved/);
61	  });
62	
63	  it("returns the base slug when nothing has claimed it", () => {
64	    expect(uniqueSlug("Website Relaunch", [])).toBe("website-relaunch");
65	  });
66	
67	  it("suffixes numerically until it finds a free slug", () => {
68	    expect(uniqueSlug("Acme", ["acme"])).toBe("acme-2");
69	    expect(uniqueSlug("Acme", ["acme", "acme-2", "acme-3"])).toBe("acme-4");
70	  });
71	
