/**
 * Maps thrown domain errors onto `AppErrorShape`.
 *
 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
 * `ZodError`); Server Actions and Route Handlers never propagate those to the
 * client. Everything funnels through `toAppError()` so one thrown class maps
 * to exactly one `ErrorCode` and one HTTP status, app-wide.
 *
 * Error classes outside that enumerated set (the action layer's own
 * `UnauthorizedActionError`, `RateLimitedError`, `PlanLimitError`, etc., plus
 * ad-hoc service errors like `EmailAlreadyExistsError`) are not imported here
 * — doing so would point `@/lib` back at `@/actions`. They are still
 * translated faithfully: every one of them declares the exact `readonly code`
 * it maps to, and the fallback below reads that field generically instead of
 * naming each class.
 */
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
import { ZodError, type ZodIssue } from "zod";

/** True for any thrown value that self-declares a code this app recognizes. */
function hasKnownErrorCode(error: unknown): error is Error & { code: ErrorCode } {
  return (
    error instanceof Error &&
    "code" in error &&
    typeof (error as { code?: unknown }).code === "string" &&
    (error as { code: string }).code in HTTP_STATUS_BY_CODE
  );
}

