function registerInput(overrides: Partial<{ name: string; email: string }>) {
  return {
    name: overrides.name ?? "Normal Name",
    email: overrides.email ?? "person@example.com",
    password: basePassword,
    confirmPassword: basePassword,
    acceptTerms: true as const,
  };
}

describe("scratch: sign-up ADR conformance", () => {
  it("reserved name signs up fine", async () => {
    const { org } = await register(registerInput({ name: "Admin", email: "admin1@example.com" }));
    expect(org.slug).not.toBe("admin");
    expect(org.name).toBe("Admin's workspace");
  });

  it("short name 'J' signs up fine", async () => {
    const { org } = await register(registerInput({ name: "J", email: "j1@example.com" }));
    expect(org.slug.length).toBeGreaterThanOrEqual(2);
  });

  it("short name 'Al' signs up fine", async () => {
    const { org } = await register(registerInput({ name: "Al", email: "al1@example.com" }));
    expect(org.slug).toBe("al");
  });

  it("non-Latin name signs up fine", async () => {
    const { org } = await register(registerInput({ name: "山田", email: "yamada1@example.com" }));
    expect(org.slug).toBe("workspace");
  });

  it("case-insensitive email: second signup with different case is a conflict, not a new account", async () => {
    await register(registerInput({ name: "First", email: "CaseTest@Example.com" }));
    await expect(
      register(registerInput({ name: "Second", email: "casetest@example.com" })),
    ).rejects.toMatchObject({ code: "conflict" });
  });

  it("duplicate email maps to a conflict AppErrorShape", async () => {
    await register(registerInput({ name: "First", email: "dup@example.com" }));
    try {
      await register(registerInput({ name: "Second", email: "dup@example.com" }));
      throw new Error("expected to throw");
    } catch (error) {
      const shape = toAppError(error);
      expect(shape.code).toBe("conflict");
    }
  });

  it("very long name truncates the workspace name to fit", async () => {
    const longName = "x".repeat(80);
    const { org } = await register(registerInput({ name: longName, email: "longname@example.com" }));
    expect(org.name.length).toBeLessThanOrEqual(64);
    expect(org.name.endsWith("'s workspace")).toBe(true);
  });

  it("login after signing up with a different email case works", async () => {
    await register(registerInput({ name: "Caser", email: "Mixed@Example.COM" }));
    const { user } = await login({ email: "mixed@example.com", password: basePassword, rememberMe: false });
    expect(user.email).toBe("mixed@example.com");
  });
});

