cat >> tests/_scratch.verify.test.ts << 'EOF'

describe("scratch: more coverage", () => {
  it("Billing, Support, Taskflow names all sign up fine", async () => {
    const names = ["Billing", "Support", "Taskflow"];
    let i = 0;
    for (const name of names) {
      i += 1;
      const { org } = await register(registerInput({ name, email: `person${i}@example.com` }));
      expect(org.slug).not.toBe(name.toLowerCase());
    }
  });

  it("registerAction throttles after capacity is exhausted", async () => {
    const { registerAction } = await import("@/actions/auth/register");
    let lastResult;
    for (let i = 0; i < 40; i += 1) {
      lastResult = await registerAction({
        name: "Bob",
        email: `bob${i}@example.com`,
        password: basePassword,
        confirmPassword: basePassword,
        acceptTerms: true,
      });
    }
    expect(lastResult?.ok).toBe(false);
    if (lastResult?.ok === false) {
      expect(lastResult.error.code).toBe("rate_limited");
      expect(lastResult.error.message).not.toMatch(/something went wrong/i);
    }
  });
});
EOF
npx vitest run tests/_scratch.verify.test.ts 2>&1 | tail -80

